ALTER TABLE public.invitations ADD COLUMN first_name text NOT NULL DEFAULT '', ADD COLUMN last_name text NOT NULL DEFAULT '';
CREATE TABLE public.enrichment_cache(user_id uuid NOT NULL REFERENCES public.profiles(user_id) ON DELETE CASCADE, linkedin_url text NOT NULL, result jsonb, success boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,linkedin_url));
GRANT ALL ON public.enrichment_cache TO service_role;
ALTER TABLE public.enrichment_cache ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.ai_calls(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(user_id) ON DELETE CASCADE, function text NOT NULL CHECK(function IN ('tags','pitch','search','icebreakers')), created_at timestamptz NOT NULL DEFAULT now(), success boolean NOT NULL DEFAULT false);
GRANT ALL ON public.ai_calls TO service_role;
ALTER TABLE public.ai_calls ENABLE ROW LEVEL SECURITY;
CREATE INDEX ai_calls_limit_idx ON public.ai_calls(user_id,function,created_at);
CREATE FUNCTION public.reserve_ai_call(uid uuid, kind text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n integer; result uuid; lim integer; BEGIN IF kind NOT IN ('tags','pitch','search','icebreakers') THEN RAISE EXCEPTION 'Invalid kind'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(uid::text,4)); lim:=CASE kind WHEN 'pitch' THEN 20 WHEN 'search' THEN 60 WHEN 'icebreakers' THEN 10 ELSE 20 END; SELECT count(*) INTO n FROM public.ai_calls WHERE user_id=uid AND function=kind AND (kind IN ('pitch','tags') OR created_at>now()-interval '1 hour'); IF n>=lim THEN RETURN NULL; END IF; INSERT INTO public.ai_calls(user_id,function) VALUES(uid,kind) RETURNING id INTO result; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.reserve_ai_call(uuid,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.reserve_ai_call(uuid,text) TO service_role;
CREATE FUNCTION public.reserve_enrichment(uid uuid, url text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM pg_advisory_xact_lock(hashtextextended(uid::text,5)); IF EXISTS(SELECT 1 FROM public.enrichment_cache WHERE user_id=uid AND linkedin_url=url) OR (SELECT count(*) FROM public.enrichment_cache WHERE user_id=uid)>=5 THEN RETURN false; END IF; INSERT INTO public.enrichment_cache(user_id,linkedin_url) VALUES(uid,url); RETURN true; END $$;
REVOKE ALL ON FUNCTION public.reserve_enrichment(uuid,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.reserve_enrichment(uuid,text) TO service_role;
CREATE TABLE public.session_feedback(user_id uuid NOT NULL REFERENCES public.profiles(user_id) ON DELETE CASCADE, session_id text NOT NULL, choices text[] NOT NULL DEFAULT '{}', comment text NOT NULL DEFAULT '' CHECK(char_length(comment)<=500), updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,session_id), CHECK(choices <@ ARRAY['actionable','learned','engaging','too_technical','too_theoretical','too_salesy']::text[]));
GRANT SELECT ON public.session_feedback TO authenticated;
GRANT ALL ON public.session_feedback TO service_role;
ALTER TABLE public.session_feedback ENABLE ROW LEVEL SECURITY;
CREATE POLICY feedback_read ON public.session_feedback FOR SELECT TO authenticated USING(public.is_active_member(auth.uid()) AND public.is_active_member(user_id) AND NOT EXISTS(SELECT 1 FROM public.blocks b WHERE b.blocker_id=auth.uid() AND b.blocked_id=session_feedback.user_id));
CREATE FUNCTION public.feedback_counts(sid text) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT COALESCE(jsonb_object_agg(choice,n),'{}'::jsonb) FROM (SELECT choice,count(*) n FROM public.session_feedback f CROSS JOIN LATERAL unnest(f.choices) choice WHERE f.session_id=sid AND public.is_active_member(auth.uid()) AND public.is_active_member(f.user_id) GROUP BY choice) x $$;
REVOKE ALL ON FUNCTION public.feedback_counts(text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.feedback_counts(text) TO authenticated;
CREATE FUNCTION public.feedback_comments(sid text) RETURNS TABLE(user_id uuid,first_name text,last_name text,choices text[],comment text,updated_at timestamptz) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT f.user_id,p.first_name,p.last_name,f.choices,f.comment,f.updated_at FROM public.session_feedback f JOIN public.profiles p ON p.user_id=f.user_id WHERE f.session_id=sid AND public.is_active_member(auth.uid()) AND public.is_active_member(f.user_id) AND NOT EXISTS(SELECT 1 FROM public.blocks b WHERE b.blocker_id=auth.uid() AND b.blocked_id=f.user_id) ORDER BY f.updated_at DESC $$;
REVOKE ALL ON FUNCTION public.feedback_comments(text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.feedback_comments(text) TO authenticated;
CREATE TABLE public.purge_control(id boolean PRIMARY KEY DEFAULT true CHECK(id), paused boolean NOT NULL DEFAULT true, preserve_user_ids uuid[] NOT NULL DEFAULT '{}', lease_until timestamptz, lease_id uuid, completed_at timestamptz, last_error text);
GRANT ALL ON public.purge_control TO service_role;
ALTER TABLE public.purge_control ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.claim_purge(claim uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.purge_control SET lease_id=claim,lease_until=now()+interval '2 minutes' WHERE id=true AND NOT paused AND completed_at IS NULL AND now()>='2026-12-16 23:00:00+00' AND (lease_until IS NULL OR lease_until<now()) AND cardinality(preserve_user_ids)=2; RETURN FOUND; END $$;
REVOKE ALL ON FUNCTION public.claim_purge(uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.claim_purge(uuid) TO service_role;